function correlationMarkup(snapshot: PublicSnapshot): string {
  const codes = snapshot.assets.map((asset) => asset.code);
  const head = codes.map((code) => `<th>${escapeHtml(labelForCode(snapshot, code))}</th>`).join('');
  const rows = codes.map((left) => {
    const asset = snapshot.assets.find((item) => item.code === left);
    const cells = codes.map((right) => {
      const value = snapshot.diagnostics.correlation[left][right];
      const strength = Math.min(1, Math.abs(value));
      return `<td><span class="correlation-cell ${value < 0 ? 'inverse' : ''}" style="--strength:${strength}">${number(value)}</span></td>`;
    }).join('');
    return `<tr><th><strong>${escapeHtml(instrumentLabel(left, asset?.name))}</strong><small>${escapeHtml(asset?.role ?? '')}</small></th>${cells}</tr>`;
  }).join('');
  const equityCount = snapshot.assets.filter((asset) => asset.assetClass === 'EQUITY').length;
  return `<div class="correlation-layout"><div class="table-scroll"><table class="correlation-table"><thead><tr><th>资产</th>${head}</tr></thead><tbody>${rows}</tbody></table></div><aside><p class="eyebrow">如何阅读</p><h3>相关性不是常数</h3><p>数值越接近 1，近期同涨同跌越明显；越接近 −1，分散作用越强。当前${equityCount}只权益 ETF 的平均相关性为 <strong>${number(snapshot.diagnostics.averageEquityCorrelation)}</strong>，${snapshot.assets.length}资产平均为 <strong>${number(snapshot.diagnostics.averagePairCorrelation)}</strong>。</p><small>${escapeHtml(snapshot.diagnostics.method)}</small></aside></div>`;
}

function correlationSummaryMarkup(snapshot: PublicSnapshot): string {
  type CorrelationPair = { left: PublicAsset; right: PublicAsset; value: number };
  const pairs: CorrelationPair[] = snapshot.assets.flatMap((left, index) => snapshot.assets.slice(index + 1).map((right) => ({
    left,
    right,
    value: snapshot.diagnostics.correlation[left.code]?.[right.code],
  }))).filter((pair): pair is CorrelationPair => typeof pair.value === 'number' && Number.isFinite(pair.value));
  if (!pairs.length) return '';
  const mostSynchronous = [...pairs].sort((left, right) => right.value - left.value)[0]!;
  const mostDiversifying = [...pairs].sort((left, right) => left.value - right.value)[0]!;
  const pairLabel = (pair: CorrelationPair): string => `${instrumentLabel(pair.left.code, pair.left.name)} / ${instrumentLabel(pair.right.code, pair.right.name)}`;
  return `<section class="mobile-correlation-summary" aria-label="移动端组合分散摘要"><div><span>近期最高正相关</span><strong>${escapeHtml(pairLabel(mostSynchronous))}</strong><small>${number(mostSynchronous.value)}</small></div><div><span>近期最强分散关系</span><strong>${escapeHtml(pairLabel(mostDiversifying))}</strong><small>${number(mostDiversifying.value)}</small></div><div><span>七资产平均相关</span><strong>${number(snapshot.diagnostics.averagePairCorrelation)}</strong><small>相关性会随时间变化</small></div></section>`;
}

