import type { HouseholdDecisionState } from './app-state';
import { escapeHtml, percent } from './format';
import type { PublicSnapshot } from './types';

function decisionHref(decision: HouseholdDecisionState, root: string): string | null {
  if (decision.actionTarget === 'DATA_ISSUES') return `${root}data/index.html#blocking-issues`;
  if (decision.actionTarget === 'MONTH_RECORD') return `${root}portfolio/index.html#execution-history`;
  return null;
}

export function householdActionMarkup(decision: HouseholdDecisionState, root: string): string {
  const href = decisionHref(decision, root);
  const opensLedger = decision.actionTarget === 'HOLDINGS_EDITOR' || decision.actionTarget === 'PREMIUM_EDITOR';
  const control = href
    ? `<a class="primary decision-primary-action" href="${href}">${escapeHtml(decision.actionLabel)}</a>`
    : opensLedger
      ? `<button type="button" class="primary decision-primary-action" data-open-portfolio${decision.focusCode ? ` data-focus-field="premium-${escapeHtml(decision.focusCode)}"` : ''}>${escapeHtml(decision.actionLabel)}</button>`
      : `<button type="button" class="primary decision-primary-action" data-operation-action="${decision.action}">${escapeHtml(decision.actionLabel)}</button>`;
  return `<div class="state-action" data-decision-state="${decision.key}">${control}<small>${escapeHtml(decision.actionConsequence)}</small></div>`;
}

export function crossPageAction(
  href: string,
  eyebrow: string,
  title: string,
  note: string,
  extraClass = '',
  download = false,
): string {
  return `<a class="action-row ${extraClass}" href="${href}"${download ? ' download' : ''}><span><small>${escapeHtml(eyebrow)}</small><strong>${escapeHtml(title)}</strong><em>${escapeHtml(note)}</em></span><b aria-hidden="true">›</b></a>`;
}

export function riskBudgetRange(snapshot: PublicSnapshot): string {
  const minimum = snapshot.allocationModel.equityMin;
  const maximum = snapshot.allocationModel.equityMax;
  const target = snapshot.risk.confirmedEquityTarget;
  const position = Math.max(0, Math.min(100, (target - minimum) / Math.max(.0001, maximum - minimum) * 100));
  const label = `只读权益预算：最低 ${percent(minimum)}，本期目标 ${percent(target)}，战略上限 ${percent(maximum)}，不可拖动`;
  return `<div class="risk-budget-range" role="img" aria-label="${escapeHtml(label)}"><div><span>${percent(minimum)}<small>最低权益预算</small></span><b>${percent(target)}<small>本期目标</small></b><span>${percent(maximum)}<small>战略上限</small></span></div><i aria-hidden="true"><b style="left:${position}%"></b></i><p>只读预算刻度 · 不可拖动</p></div>`;
}
